local NeedleMaker = {}
local PRODUCTS = {
    sewing_needle = { name = "Šivalna igla", steelCost = 1, time = 1, cost = 3, quantity = 20, description = "Šivalne igle." },
    embroidery_needle = { name = "Vezilna igla", steelCost = 1, time = 2, cost = 8, quantity = 10, description = "Fine igle za vezenje." },
    safety_pin = { name = "Varnostna zaponka", brassCost = 1, time = 1, cost = 5, quantity = 15, description = "Varnostne zaponke." },
    hat_pin = { name = "Klobučna igla", steelCost = 1, brassCost = 1, time = 2, cost = 10, quantity = 10, description = "Igle za klobuke." },
    silver_needle = { name = "Srebrna igla", silverCost = 1, time = 3, cost = 30, quantity = 5, prestige = 2, happiness = 1, description = "Srebrne igle za luksuz." },
    royal_needle_set = { name = "Kraljevski set igel", goldCost = 1, silverCost = 1, steelCost = 2, time = 5, cost = 100, quantity = 3, prestige = 10, happiness = 3, description = "Komplet igel za kraljevske vezilje." },
}
local BUILDINGS = {
    workshop = { name = "Iglarska delavnica", cost = { gold = 150, wood = 100, iron = 30 }, upkeep = 3, qualityBonus = 5 },
    wire_drawing = { name = "Žična vlečilnica", cost = { gold = 500, wood = 200, stone = 100, iron = 50 }, upkeep = 12, qualityBonus = 15 },
    grinding_shop = { name = "Brusilnica", cost = { gold = 800, wood = 200, stone = 200, iron = 50 }, upkeep = 20, qualityBonus = 20 },
    royal_needle_maker = { name = "Kraljevski iglar", cost = { gold = 2500, wood = 400, stone = 500, gold = 30 }, upkeep = 50, qualityBonus = 35, prestigeBonus = 15 },
}
NeedleMaker.steelStock = 12; NeedleMaker.brassStock = 5; NeedleMaker.silverStock = 3; NeedleMaker.goldStock = 2
NeedleMaker.productStock = {}; NeedleMaker.buildings = {}; NeedleMaker.maker = nil; NeedleMaker.activeMaking = {}; NeedleMaker.totalProducts = 0; NeedleMaker.dayTimer = 0
function NeedleMaker.init() NeedleMaker.steelStock=12; NeedleMaker.brassStock=5; NeedleMaker.silverStock=3; NeedleMaker.goldStock=2; NeedleMaker.productStock={}; NeedleMaker.buildings={}; NeedleMaker.maker=nil; NeedleMaker.activeMaking={}; NeedleMaker.totalProducts=0; NeedleMaker.dayTimer=0; print("[NeedleMaker] Royal Needle & Pin Maker System initialized (6 products, 4 buildings)") end
function NeedleMaker.hireMaker(n,s) s=s or math.random(30,75); local c=150+s*3; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; NeedleMaker.maker={name=n or ("Iglar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Iglar najet: %s (spretnost: %d)",NeedleMaker.maker.name,s),"success") end; return true end
function NeedleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function NeedleMaker.build(id) local ok,e=NeedleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(NeedleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function NeedleMaker.getQualityBonus() local b=0; for _,bd in ipairs(NeedleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function NeedleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.steelCost and NeedleMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.brassCost and NeedleMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and NeedleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and NeedleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #NeedleMaker.buildings==0 then return false,"Potrebna delavnica" end; if not NeedleMaker.maker then return false,"Potreben iglar" end; return true end
function NeedleMaker.make(pt) local ok,e=NeedleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.steelCost then NeedleMaker.steelStock=NeedleMaker.steelStock-d.steelCost end; if d.brassCost then NeedleMaker.brassStock=NeedleMaker.brassStock-d.brassCost end; if d.silverCost then NeedleMaker.silverStock=NeedleMaker.silverStock-d.silverCost end; if d.goldCost then NeedleMaker.goldStock=NeedleMaker.goldStock-d.goldCost end; local t=d.time; if NeedleMaker.maker then t=math.max(1,t-math.floor(NeedleMaker.maker.skill/15)) end; table.insert(NeedleMaker.activeMaking,{id="needle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,quantity=d.quantity or 1,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function NeedleMaker.completeMaking(m) local q=1.0+(NeedleMaker.getQualityBonus()/100); if NeedleMaker.maker then q=q+(NeedleMaker.maker.skill/200) end; q=math.min(2.0,q); NeedleMaker.productStock[m.productType]=(NeedleMaker.productStock[m.productType] or 0)+m.quantity; NeedleMaker.totalProducts=NeedleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if NeedleMaker.maker then NeedleMaker.maker.itemsMade=NeedleMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then NeedleMaker.maker.skill=math.min(100,NeedleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igle izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function NeedleMaker.update(dt) if not _G.state then return end; NeedleMaker.dayTimer=NeedleMaker.dayTimer+dt; if NeedleMaker.dayTimer>=30 then NeedleMaker.dayTimer=0; for i=#NeedleMaker.activeMaking,1,-1 do local m=NeedleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then NeedleMaker.completeMaking(m); table.remove(NeedleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(NeedleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if NeedleMaker.maker then tu=tu+4 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function NeedleMaker.getStats() return {steelStock=NeedleMaker.steelStock,brassStock=NeedleMaker.brassStock,silverStock=NeedleMaker.silverStock,goldStock=NeedleMaker.goldStock,productStock=NeedleMaker.productStock,numBuildings=#NeedleMaker.buildings,hasMaker=NeedleMaker.maker~=nil,makerName=NeedleMaker.maker and NeedleMaker.maker.name or "—",makerSkill=NeedleMaker.maker and NeedleMaker.maker.skill or 0,activeMaking=#NeedleMaker.activeMaking,totalProducts=NeedleMaker.totalProducts} end
return NeedleMaker
